{
  "root": "main_stack",
  "state": {},
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title_h1",
        "niche_zero_section_title",
        "niche_zero_card",
        "grinder_comparison_title",
        "grinder_table",
        "recommendation_summary_title",
        "recommendation_overall",
        "recommendation_budget",
        "recommendation_note",
        "quick_actions_label",
        "niche_zero_button",
        "grinder_reviews_button",
        "sources_label",
        "espresso_data_button"
      ]
    },
    "title_h1": {
      "type": "Text",
      "props": {
        "text": "Home Espresso Grinder Comparison",
        "variant": "h1"
      },
      "children": []
    },
    "niche_zero_section_title": {
      "type": "Text",
      "props": {
        "text": "Niche Zero: The Ideal Compact Solution",
        "variant": "h2"
      },
      "children": []
    },
    "niche_zero_card": {
      "type": "Card",
      "props": {},
      "children": [
        "niche_zero_card_text1",
        "niche_zero_card_text2"
      ]
    },
    "niche_zero_card_text1": {
      "type": "Text",
      "props": {
        "text": "The Niche Zero is a popular choice for home espresso enthusiasts due to its single-dosing workflow and excellent grind quality."
      },
      "children": []
    },
    "niche_zero_card_text2": {
      "type": "Text",
      "props": {
        "text": "It's known for minimal retention and consistent grinds across a wide range of settings, making it versatile for various brew methods."
      },
      "children": []
    },
    "grinder_comparison_title": {
      "type": "Text",
      "props": {
        "text": "Grinder Comparison Table",
        "variant": "h2"
      },
      "children": []
    },
    "grinder_table": {
      "type": "Table",
      "props": {
        "columns": [
          {
            "key": "model",
            "label": "Model"
          },
          {
            "key": "type",
            "label": "Type"
          },
          {
            "key": "price",
            "label": "Price"
          },
          {
            "key": "retention",
            "label": "Retention"
          },
          {
            "key": "grind_quality",
            "label": "Grind Quality"
          }
        ],
        "rows": [
          {
            "model": "Niche Zero",
            "type": "Conical Burr",
            "price": "$650",
            "retention": "Very Low",
            "grind_quality": "Excellent"
          },
          {
            "model": "Eureka Mignon Specialita",
            "type": "Flat Burr",
            "price": "$700",
            "retention": "Low",
            "grind_quality": "Excellent"
          },
          {
            "model": "Baratza Sette 270Wi",
            "type": "Conical Burr",
            "price": "$500",
            "retention": "Very Low",
            "grind_quality": "Good"
          }
        ],
        "domain": "comparison",
        "preferredPresentation": "table"
      },
      "children": []
    },
    "recommendation_summary_title": {
      "type": "Text",
      "props": {
        "text": "Recommendations",
        "variant": "h2"
      },
      "children": []
    },
    "recommendation_overall": {
      "type": "Text",
      "props": {
        "text": "Overall Best: Niche Zero for its versatility and single-dosing workflow."
      },
      "children": []
    },
    "recommendation_budget": {
      "type": "Text",
      "props": {
        "text": "Budget-Friendly: Baratza Sette 270Wi offers great value for its performance."
      },
      "children": []
    },
    "recommendation_note": {
      "type": "Text",
      "props": {
        "text": "Consider your workflow and budget when choosing a grinder. Flat burrs often excel at espresso, while conical burrs are more versatile."
      },
      "children": []
    },
    "quick_actions_label": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h3"
      },
      "children": []
    },
    "niche_zero_button": {
      "type": "Button",
      "props": {
        "label": "Buy Niche Zero"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.nichecoffee.com/products/niche-zero"
          }
        }
      },
      "children": []
    },
    "grinder_reviews_button": {
      "type": "Button",
      "props": {
        "label": "Read Grinder Reviews"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.home-barista.com/grinders/"
          }
        }
      },
      "children": []
    },
    "sources_label": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h3"
      },
      "children": []
    },
    "espresso_data_button": {
      "type": "Button",
      "props": {
        "label": "Espresso Grinder Data"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.baratza.com/grinder-comparison/"
          }
        }
      },
      "children": []
    }
  }
}
